// Full semantic and generated command audit. This dedicated target runs every case directly.

// golden: packs/mafiascum/golden/reveal_town_day.json
async fn host_resolve_phase_reveals_town_alignment_without_role(pool: PgPool) {
    let host = user("host_alignment_reveal");
    let game = Uuid::new_v4();

    handle(
        &pool,
        &host,
        Command::CreateGame {
            game,
            pack: "mafiascum".into(),
            cohost_denied: vec![],
        },
    )
    .await
    .unwrap();
    for (slot, occupant, role) in [
        ("slot_1", "user_1", "innocent_child"),
        ("slot_2", "user_2", "vanilla_townie"),
        ("slot_3", "user_3", "mafia_goon"),
    ] {
        handle(
            &pool,
            &host,
            Command::AddSlot {
                game,
                slot: slot.into(),
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &host,
            commands::seat_persona! {
                game,
                slot: slot.into(),
                user: occupant,
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &host,
            Command::AssignRole {
                game,
                slot: slot.into(),
                role_key: role.into(),
            },
        )
        .await
        .unwrap();
    }

    handle(
        &pool,
        &host,
        Command::StartGame {
            game,
            phase: domain::phase::PhaseId::parse("D01").expect("static test phase id is canonical"),
        },
    )
    .await
    .unwrap();
    handle(
        &pool,
        &user("user_1"),
        Command::SubmitAction {
            game,
            action_id: "reveal_town_d01".into(),
            actor_slot: "slot_1".into(),
            template_id: "reveal_town".into(),
            targets: vec![],
            grant_id: None,
        },
    )
    .await
    .expect("innocent child submits public alignment reveal");

    let ack = handle(&pool, &host, Command::ResolvePhase { game, seed: 7309 })
        .await
        .expect("host resolves public alignment reveal");
    assert_eq!(
        ack.stream_seqs.len(),
        3,
        "alignment reveal resolution appends ResolutionApplied, ResolutionTrace, and ThreadLocked"
    );

    let applied_payload = stored_payload(&pool, game, "ResolutionApplied").await;
    let applied = domain::validate_resolution_json(&applied_payload, domain::RESULT_VERSION)
        .expect("alignment-reveal ResolutionApplied validates");
    assert_eq!(applied.phase_id.as_str(), "D01");
    assert_eq!(applied.phase_id.kind(), domain::phase::PhaseKind::Day);
    assert!(
        applied.events.iter().any(|indexed| matches!(
            &indexed.event,
            domain::InnerEvent::AlignmentRevealed {
                slot_id,
                alignment,
                source_action,
                phase_id,
            } if slot_id == "slot_1"
                && alignment == "town"
                && source_action == "reveal_town_d01"
                && phase_id.as_str() == "D01"
                && phase_id.kind() == domain::phase::PhaseKind::Day
                && phase_id.number() == 1
        )),
        "resolution should persist the public alignment reveal"
    );
    assert!(
        !applied
            .events
            .iter()
            .any(|indexed| matches!(&indexed.event, domain::InnerEvent::PlayerKilled { .. })),
        "public alignment reveal should not kill any slot"
    );

    let projected = slot_state(&pool, game).await.unwrap();
    let revealed = projected
        .iter()
        .find(|slot| slot.slot_id == "slot_1")
        .expect("revealed slot projection");
    assert!(revealed.alive, "revealed slot remains alive");
    assert_eq!(revealed.alignment.as_deref(), Some("town"));
    assert!(revealed.alignment_revealed);
    assert!(
        !revealed.role_revealed,
        "Innocent Child reveal exposes alignment only, not role"
    );

    let thread = projections::thread_view(&pool, game, None, 50)
        .await
        .expect("thread view");
    assert!(
        thread.posts.iter().any(|post| post
            .body
            .contains("Public reveal: slot_1 revealed alignment town in D01 (reveal_town_d01).")),
        "public thread should include the alignment-only reveal"
    );

    let audit = audit_resolution_envelopes(&pool, game)
        .await
        .expect("alignment-reveal resolution audit");
    assert!(audit.ok, "alignment-reveal audit drifted: {audit:?}");
    assert_eq!(audit.audited, 1);
    assert_eq!(audit.skipped, 0);

    let projected_before = serde_json::to_string(&projected).unwrap();
    let thread_before = serde_json::to_string(&thread).unwrap();
    rebuild(&pool, game).await.expect("projection rebuild");
    assert_eq!(
        projected_before,
        serde_json::to_string(&slot_state(&pool, game).await.unwrap()).unwrap(),
        "slot_state rebuild must preserve alignment-only public reveal"
    );
    assert_eq!(
        thread_before,
        serde_json::to_string(
            &projections::thread_view(&pool, game, None, 50)
                .await
                .unwrap()
        )
        .unwrap(),
        "thread_view rebuild must preserve alignment-only public reveal"
    );
}

