#[sqlx::test(migrations = "../projections/migrations")]
async fn generated_chinese_structured_night_graphs_replay_audit_and_rebuild_deterministically(
    pool: PgPool,
) {
    for seed in [92_001_u64, 92_113, 92_227, 92_331, 92_447, 92_559] {
        let case = generated_chinese_night_case(seed);
        let resolver_seed = seed + 44_000;
        let summary = generated_pack_night_case_summary(&case, "chinese_structured", resolver_seed);
        let fixture_json =
            generated_night_case_fixture_json(&case, "chinese_structured", resolver_seed);
        let shrink_stem = format!("generated-chinese-n01-seed-{seed}");
        let game = Uuid::new_v4();
        let host = user("host_h");

        generated_handle_or_shrink(
            &pool,
            &host,
            Command::CreateGame {
                game,
                pack: "chinese_structured".into(),
                cohost_denied: vec![],
            },
            &shrink_stem,
            &fixture_json,
            &summary,
            "create Chinese generated game failed",
        )
        .await;
        for (slot, role) in &case.roster {
            generated_handle_or_shrink(
                &pool,
                &host,
                Command::AddSlot {
                    game,
                    slot: slot.clone(),
                },
                &shrink_stem,
                &fixture_json,
                &summary,
                format!("add {slot} failed"),
            )
            .await;
            generated_handle_or_shrink(
                &pool,
                &host,
                commands::seat_persona! {
                    game,
                    slot: slot.clone(),
                    user: format!("chinese_generated_seed_{seed}_user_{}", slot_number(slot)),
                },
                &shrink_stem,
                &fixture_json,
                &summary,
                format!("assign {slot} failed"),
            )
            .await;
            generated_handle_or_shrink(
                &pool,
                &host,
                Command::AssignRole {
                    game,
                    slot: slot.clone(),
                    role_key: role.clone(),
                },
                &shrink_stem,
                &fixture_json,
                &summary,
                format!("role {slot} failed"),
            )
            .await;
        }
        generated_handle_or_shrink(
            &pool,
            &host,
            Command::StartGame {
                game,
                phase: domain::phase::PhaseId::parse("N01").expect("static test phase id is canonical"),
            },
            &shrink_stem,
            &fixture_json,
            &summary,
            "start Chinese generated game failed",
        )
        .await;

        for action in &case.actions {
            generated_handle_or_shrink(
                &pool,
                &user(&format!(
                    "chinese_generated_seed_{seed}_user_{}",
                    slot_number(&action.actor_slot)
                )),
                Command::SubmitAction {
                    game,
                    action_id: action.action_id.clone(),
                    actor_slot: action.actor_slot.clone(),
                    template_id: action.template_id.clone(),
                    targets: action.targets.clone(),
                    grant_id: None,
                },
                &shrink_stem,
                &fixture_json,
                &summary,
                format!(
                    "submit {} for {} failed",
                    action.template_id, action.actor_slot
                ),
            )
            .await;
        }

        let ack = match handle(
            &pool,
            &host,
            Command::ResolvePhase {
                game,
                seed: resolver_seed,
            },
        )
        .await
        {
            Ok(ack) => ack,
            Err(err) => {
                panic!(
                    "{}",
                    generated_shrink_failure_message(
                        &pool,
                        &shrink_stem,
                        &fixture_json,
                        &summary,
                        format!("resolve Chinese generated graph failed: {err}"),
                    )
                    .await
                )
            }
        };
        if ack.stream_seqs.len() != 3 {
            panic!(
                "{}",
                generated_shrink_failure_message(
                    &pool,
                    &shrink_stem,
                    &fixture_json,
                    &summary,
                    format!(
                        "Chinese generated resolve events plus phase lock expected 3 stream seqs, got {}",
                        ack.stream_seqs.len()
                    ),
                )
                .await
            );
        }

        let applied_payload = resolution_payload(&pool, game, "N01", seed).await;
        let applied =
            match domain::validate_resolution_json(&applied_payload, domain::RESULT_VERSION) {
                Ok(applied) => applied,
                Err(err) => {
                    panic!(
                        "{}",
                        generated_shrink_failure_message(
                            &pool,
                            &shrink_stem,
                            &fixture_json,
                            &summary,
                            format!("ResolutionApplied invalid: {err}"),
                        )
                        .await
                    )
                }
            };
        if applied.events.len() >= 200 {
            panic!(
                "{}",
                generated_shrink_failure_message(
                    &pool,
                    &shrink_stem,
                    &fixture_json,
                    &summary,
                    format!(
                        "Chinese generated graph event count should stay bounded: {}",
                        applied.events.len()
                    ),
                )
                .await
            );
        }
        let representative_event = match applied.events.iter().find_map(|indexed| {
            let outcome = match &indexed.event {
                domain::InnerEvent::InvestigationResult { .. } => "investigation_result",
                domain::InnerEvent::PlayersLinked { .. } => "players_linked",
                domain::InnerEvent::PlayerKilled { .. } => "player_killed",
                domain::InnerEvent::PlayerSaved { .. } => "player_saved",
                domain::InnerEvent::EffectsMarked { .. } => "effects_marked",
                domain::InnerEvent::RetaliationArmed { .. } => "retaliation_armed",
                domain::InnerEvent::PhaseAnnouncement(_) => return None,
                _ => return None,
            };
            Some((indexed.index, outcome))
        }) {
            Some(event) => event,
            None => {
                panic!(
                    "{}",
                    generated_shrink_failure_message(
                        &pool,
                        &shrink_stem,
                        &fixture_json,
                        &summary,
                        "Chinese generated night should emit a traceable inner event".to_string(),
                    )
                    .await
                )
            }
        };

        let audit = match audit_resolution_envelopes(&pool, game).await {
            Ok(audit) => audit,
            Err(err) => {
                panic!(
                    "{}",
                    generated_shrink_failure_message(
                        &pool,
                        &shrink_stem,
                        &fixture_json,
                        &summary,
                        format!("audit_resolution failed: {err}"),
                    )
                    .await
                )
            }
        };
        if !audit.ok {
            panic!(
                "{}",
                generated_shrink_failure_message(
                    &pool,
                    &shrink_stem,
                    &fixture_json,
                    &summary,
                    format!("Chinese generated resolution audit drifted: {audit:?}"),
                )
                .await
            );
        }
        if audit.audited != 1 || audit.skipped != 0 {
            panic!(
                "{}",
                generated_shrink_failure_message(
                    &pool,
                    &shrink_stem,
                    &fixture_json,
                    &summary,
                    format!(
                        "expected one audited Chinese generated phase and no skipped envelopes, got audited={} skipped={}",
                        audit.audited, audit.skipped
                    ),
                )
                .await
            );
        }

        let trace_report = match inspect_resolution_traces(&pool, game, None).await {
            Ok(report) => report,
            Err(err) => {
                panic!(
                    "{}",
                    generated_shrink_failure_message(
                        &pool,
                        &shrink_stem,
                        &fixture_json,
                        &summary,
                        format!("inspect_trace failed: {err}"),
                    )
                    .await
                )
            }
        };
        if trace_report.traces.len() != 1 {
            panic!(
                "{}",
                generated_shrink_failure_message(
                    &pool,
                    &shrink_stem,
                    &fixture_json,
                    &summary,
                    format!(
                        "expected one Chinese generated trace, got {}",
                        trace_report.traces.len()
                    ),
                )
                .await
            );
        }
        let result_contract_source =
            format!("domain::resolve/result_version:{}", applied.result_version);
        let result_contract_outcome = format!("{} inner events validated", applied.counts.events);
        if let Err(reason) = check_anchored_inspection_decision(
            &trace_report,
            InspectionDecisionExpectation {
                phase_id: "N01",
                stage: "result_contract",
                source: &result_contract_source,
                outcome: &result_contract_outcome,
                detail: serde_json::json!({
                    "kills": applied.counts.kills,
                    "saves": applied.counts.saves,
                }),
            },
        ) {
            panic!(
                "{}",
                generated_shrink_failure_message(
                    &pool,
                    &shrink_stem,
                    &fixture_json,
                    &summary,
                    reason,
                )
                .await
            );
        }
        let representative_source = format!("event_index:{}", representative_event.0);
        if let Err(reason) = check_anchored_inspection_decision(
            &trace_report,
            InspectionDecisionExpectation {
                phase_id: "N01",
                stage: "inner_event",
                source: &representative_source,
                outcome: representative_event.1,
                detail: empty_inspection_detail(),
            },
        ) {
            panic!(
                "{}",
                generated_shrink_failure_message(
                    &pool,
                    &shrink_stem,
                    &fixture_json,
                    &summary,
                    reason,
                )
                .await
            );
        }

        let projection_audit = match audit_rebuild(&pool, game).await {
            Ok(report) => report,
            Err(err) => {
                panic!(
                    "{}",
                    generated_shrink_failure_message(
                        &pool,
                        &shrink_stem,
                        &fixture_json,
                        &summary,
                        format!("audit_rebuild failed: {err}"),
                    )
                    .await
                )
            }
        };
        if !projection_audit.ok {
            panic!(
                "{}",
                generated_shrink_failure_message(
                    &pool,
                    &shrink_stem,
                    &fixture_json,
                    &summary,
                    format!(
                        "Chinese generated projection rebuild audit drifted: {projection_audit:?}"
                    ),
                )
                .await
            );
        }
    }
}

