    let blocked = resolved
        .iter()
        .find(|(_, action_id, ..)| *action_id == "ita_better_shielded")
        .expect("better chance shielded shot resolved");
    assert!(matches!(blocked.2, domain::ItaShotOutcome::Blocked));
