// golden: packs/mafia_universe/golden/commute_mafia_blocks_investigation.json
async fn host_resolve_phase_carries_mafia_universe_commute(pool: PgPool) {
    let host = "host_mu_commute";
    let game = Uuid::new_v4();
    let h = user(host);

    handle(
        &pool,
        &h,
        Command::CreateGame {
            game,
            pack: "mafia_universe".into(),
            cohost_denied: vec![],
        },
    )
    .await
    .unwrap();
    for (slot, occupant, role) in [
        ("slot_1", "mu_commute_user_1", "mafia_goon"),
        ("slot_2", "mu_commute_user_2", "town_commuter"),
        ("slot_3", "mu_commute_user_3", "town_cop"),
        ("slot_4", "mu_commute_user_4", "town_vanilla"),
        ("slot_5", "mu_commute_user_5", "town_vanilla"),
    ] {
        handle(
            &pool,
            &h,
            Command::AddSlot {
                game,
                slot: slot.into(),
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &h,
            commands::seat_persona! {
                game,
                slot: slot.into(),
                user: occupant,
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &h,
            Command::AssignRole {
                game,
                slot: slot.into(),
                role_key: role.into(),
            },
        )
        .await
        .unwrap();
    }
    handle(
        &pool,
        &h,
        Command::StartGame {
            game,
            phase: domain::phase::PhaseId::parse("N01").expect("static test phase id is canonical"),
        },
    )
    .await
    .unwrap();

    let err = handle(
        &pool,
        &user("mu_commute_user_2"),
        Command::SubmitAction {
            game,
            action_id: "mu_commute_other_rejected_n01".into(),
            actor_slot: "slot_2".into(),
            template_id: "commute".into(),
            targets: vec!["slot_4".into()],
            grant_id: None,
        },
    )
    .await
    .expect_err("MU personal-only commuter rejects non-self target before append");
    assert_eq!(err, Reject::InvalidTarget);

    handle(
        &pool,
        &user("mu_commute_user_2"),
        Command::SubmitAction {
            game,
            action_id: "mu_commute_self_n01".into(),
            actor_slot: "slot_2".into(),
            template_id: "commute".into(),
            targets: vec!["slot_2".into()],
            grant_id: None,
        },
    )
    .await
    .expect("MU Commuter submits self-commute");
    handle(
        &pool,
        &user("mu_commute_user_1"),
        Command::SubmitAction {
            game,
            action_id: "mu_kill_commuter_n01".into(),
            actor_slot: "slot_1".into(),
            template_id: "factional_kill".into(),
            targets: vec!["slot_2".into()],
            grant_id: None,
        },
    )
    .await
    .expect("MU Goon submits kill against commuter");
    handle(
        &pool,
        &user("mu_commute_user_3"),
        Command::SubmitAction {
            game,
            action_id: "mu_cop_check_commuter_n01".into(),
            actor_slot: "slot_3".into(),
            template_id: "cop_investigate".into(),
            targets: vec!["slot_2".into()],
            grant_id: None,
        },
    )
    .await
    .expect("MU Cop submits investigation against commuter");

    handle(
        &pool,
        &h,
        Command::ResolvePhase {
            game,
            seed: 705_004,
        },
    )
    .await
    .expect("host resolves Mafia Universe commute scenario");

    let trace_payload =
        stored_payload_where(&pool, game, "ResolutionTrace", &[("phase_id", "N01")]).await;
    let trace = domain::validate_trace_json(&trace_payload, domain::TRACE_VERSION)
        .expect("valid Mafia Universe commute trace");
    assert_decision_trace(
        &trace,
        DecisionTraceExpectation {
            stage: "kill_resolution",
            source: "cause:factional_kill",
            outcome: "kill_skipped_by_target_state",
            detail: vec![
                ("action_id", serde_json::json!("mu_kill_commuter_n01")),
                ("template_id", serde_json::json!("factional_kill")),
                ("actor", serde_json::json!("slot_1")),
                ("target", serde_json::json!("slot_2")),
                ("reason", serde_json::json!("commuted")),
                ("target_tags", serde_json::json!(["commuted"])),
            ],
        },
    );
    assert_decision_trace(
        &trace,
        DecisionTraceExpectation {
            stage: "night:target_state",
            source: "action:mu_cop_check_commuter_n01",
            outcome: "action_interfered_by_target_state",
            detail: vec![
                ("action_id", serde_json::json!("mu_cop_check_commuter_n01")),
                ("template_id", serde_json::json!("cop_investigate")),
                ("actor", serde_json::json!("slot_3")),
                ("target", serde_json::json!("slot_2")),
                ("ability", serde_json::json!("Investigate")),
                ("mode", serde_json::json!("Parity")),
                ("reason", serde_json::json!("commuted")),
                ("target_tags", serde_json::json!(["commuted"])),
            ],
        },
    );

    let applied_payload = resolution_payload(&pool, game, "N01", 705_004).await;
    let applied = domain::validate_resolution_json(&applied_payload, domain::RESULT_VERSION)
        .expect("valid Mafia Universe commute result");
    assert!(applied.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::ActionInterfered { actor, reason }
            if actor == "slot_3" && reason == "untargetable"
    )));
    assert!(
        !applied.events.iter().any(|indexed| matches!(
            &indexed.event,
            domain::InnerEvent::PlayerKilled { slot_id, .. } if slot_id == "slot_2"
        )),
        "MU commuted target must not die"
    );
    assert!(
        !applied.events.iter().any(|indexed| matches!(
            &indexed.event,
            domain::InnerEvent::InvestigationResult { investigator, target, .. }
                if investigator == "slot_3" && target == "slot_2"
        )),
        "MU commuted target should block the Cop result"
    );

    let slots = slot_state(&pool, game).await.unwrap();
    assert!(
        slots
            .iter()
            .find(|slot| slot.slot_id == "slot_2")
            .unwrap()
            .alive,
        "MU commuted target should survive the skipped kill"
    );
    assert!(
        slot_effects(&pool, game)
            .await
            .unwrap()
            .iter()
            .all(|effect| effect.effect != "commuted"),
        "resolution-scoped MU commute must not persist as a durable slot_effect row"
    );
    assert!(
        projections::player_investigation_results(&pool, game)
            .await
            .expect("read MU commute private investigation results")
            .is_empty(),
        "blocked MU commute investigation should not project a private result"
    );

    let slots_before = serde_json::to_string(&slots).unwrap();
    let projection_audit = audit_rebuild(&pool, game)
        .await
        .expect("Mafia Universe commute audit_rebuild");
    assert!(
        projection_audit.ok,
        "Mafia Universe commute projection rebuild audit drifted: {projection_audit:?}"
    );
    assert_eq!(
        slots_before,
        serde_json::to_string(&slot_state(&pool, game).await.unwrap()).unwrap(),
        "slot_state rebuild must preserve MU commute survival"
    );
    assert!(
        slot_effects(&pool, game)
            .await
            .unwrap()
            .iter()
            .all(|effect| effect.effect != "commuted"),
        "slot_effect rebuild must preserve MU commute non-durability"
    );
    let trace_after_rebuild =
        stored_payload_where(&pool, game, "ResolutionTrace", &[("phase_id", "N01")]).await;
    assert_eq!(
        trace_payload, trace_after_rebuild,
        "projection rebuild must not rewrite persisted MU commute trace envelope"
    );

    let audit = audit_resolution_envelopes(&pool, game)
        .await
        .expect("Mafia Universe commute resolution audit");
    assert!(
        audit.ok,
        "Mafia Universe commute resolution audit drifted: {audit:?}"
    );
}

