// golden: packs/mafia_universe/golden/day_notes_announcement_last_words.json
async fn host_resolve_phase_carries_day_announcements_and_last_words(pool: PgPool) {
    let host = "host_h";
    let game = Uuid::new_v4();
    let h = user(host);

    handle(
        &pool,
        &h,
        Command::CreateGame {
            game,
            pack: "mafia_universe".into(),
            cohost_denied: vec![],
        },
    )
    .await
    .unwrap();
    for (slot, occupant, role) in [
        ("slot_1", "user_1", "town_vanilla"),
        ("slot_2", "user_2", "town_vanilla"),
        ("slot_3", "user_3", "town_vanilla"),
        ("slot_4", "user_4", "mafia_goon"),
        ("slot_5", "user_5", "mafia_goon"),
        ("slot_6", "user_6", "mafia_goon"),
    ] {
        handle(
            &pool,
            &h,
            Command::AddSlot {
                game,
                slot: slot.into(),
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &h,
            commands::seat_persona! {
                game,
                slot: slot.into(),
                user: occupant,
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &h,
            Command::AssignRole {
                game,
                slot: slot.into(),
                role_key: role.into(),
            },
        )
        .await
        .unwrap();
    }
    handle(
        &pool,
        &h,
        Command::StartGame {
            game,
            phase: domain::phase::PhaseId::parse("D02").expect("static test phase id is canonical"),
        },
    )
    .await
    .unwrap();

    append_and_project(
        &pool,
        game,
        &[eventstore::EventInput::new(
            "ResolutionApplied",
            1,
            serde_json::json!({
                "phase_id": "N01",
                "run_id": "resolution:test:N01:day_notes",
                "result_version": domain::RESULT_VERSION,
                "seed": 77,
                "counts": { "events": 3, "kills": 2, "saves": 0 },
                "events": [
                    {
                        "index": 0,
                        "kind": "PlayerKilled",
                        "payload": {
                            "slot_id": "slot_5",
                            "cause": "factional_kill",
                            "attackers": ["slot_4"],
                            "unstoppable": false
                        }
                    },
                    {
                        "index": 1,
                        "kind": "PlayerKilled",
                        "payload": {
                            "slot_id": "slot_2",
                            "cause": "poison",
                            "attackers": ["slot_6"],
                            "unstoppable": true
                        }
                    },
                    {
                        "index": 2,
                        "kind": "PhaseAnnouncement",
                        "payload": {
                            "phase_id": "N01",
                            "deaths": [
                                { "slot_id": "slot_5", "cause": "night_kill" },
                                { "slot_id": "slot_2", "cause": "poison" }
                            ]
                        }
                    }
                ],
                "started_at": 40,
                "finished_at": 40
            }),
            eventstore::ActorId::System,
            0,
        )],
    )
    .await
    .unwrap();

    for (seq, actor) in [(1, "slot_1"), (2, "slot_4"), (3, "slot_6")] {
        append_and_project(
            &pool,
            game,
            &[eventstore::EventInput::new(
                "VoteSubmitted",
                1,
                serde_json::json!({
                    "phase_id": "D02",
                    "actor": actor,
                    "target": "slot_3"
                }),
                eventstore::ActorId::Slot(actor.into()),
                0,
            )],
        )
        .await
        .unwrap_or_else(|err| panic!("append vote {seq}: {err}"));
    }

    handle(&pool, &h, Command::ResolvePhase { game, seed: 920001 })
        .await
        .expect("host resolves day notes day");

    let d02_payload =
        stored_payload_where(&pool, game, "ResolutionApplied", &[("phase_id", "D02")]).await;
    let d02 = domain::validate_resolution_json(&d02_payload, domain::RESULT_VERSION).unwrap();
    let day_notes = d02
        .events
        .iter()
        .filter_map(|indexed| match &indexed.event {
            domain::InnerEvent::DayAnnouncement(note) => Some(note),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(day_notes.len(), 2);
    assert!(
        matches!(
            day_notes.as_slice(),
            [first, second]
                if first.player_id == "slot_5"
                    && first.sequence == 0
                    && second.player_id == "slot_2"
                    && second.sequence == 1
        ),
        "prior-night death announcements should preserve PlayerKilled order"
    );
    assert!(d02.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::DayAnnouncement(note)
            if note.player_id == "slot_5"
                && note.cause == "factional_kill"
                && note.template_id.as_deref() == Some("mafia_universe_night_death_v1")
                && note.audience.as_deref() == Some("public")
                && note.attackers == vec!["slot_4".to_string()]
                && note.role_key.as_deref() == Some("mafia_goon")
                && note.role_payload == Some(domain::DayNoteRolePayload::RoleKey)
                && note.day == 2
                && note.night == 1
    )));
    assert!(d02.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::DayAnnouncement(note)
            if note.player_id == "slot_2"
                && note.cause == "poison"
                && note.attackers == vec!["slot_6".to_string()]
                && note.role_key.as_deref() == Some("town_vanilla")
                && note.role_payload == Some(domain::DayNoteRolePayload::RoleKey)
                && note.sequence == 1
    )));
    assert!(d02.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::LastWordsRecorded(note)
            if note.player_id == "slot_3"
                && note.reason == "lynch"
                && note.template_id.as_deref() == Some("mafia_universe_last_words_v1")
                && note.audience.as_deref() == Some("public")
                && note.window.as_deref() == Some("post_lynch")
                && note.vote.winner.as_deref() == Some("slot_3")
                && (note.vote.total_weight - 4.0).abs() < f64::EPSILON
    )));
    assert!(d02.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::PlayerKilled {
            slot_id,
            cause,
            unstoppable,
            ..
        } if slot_id == "slot_3" && cause == "day_vote" && *unstoppable
    )));
    assert!(d02.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::PhaseAnnouncement(announcement)
            if announcement.phase_id.as_str() == "D02"
                && announcement.template_id.as_deref() == Some("mafia_universe_day_death_v1")
                && announcement.audience.as_deref() == Some("public")
                && announcement.deaths == vec![domain::Death {
                    slot_id: "slot_3".to_string(),
                    cause: "lynch".to_string(),
                    template_id: Some("mafia_universe_lynch_death_v1".to_string()),
                    audience: Some("public".to_string()),
                }]
    )));

    let thread = projections::thread_view(&pool, game, None, 50)
        .await
        .expect("thread view includes engine announcements");
    let d02_post = thread
        .posts
        .iter()
        .find(|post| {
            post.phase_id.as_ref().is_some_and(|phase_id| phase_id.as_str() == "D02")
                && matches!(&post.author, projections::GameThreadAuthor::System)
                && post.body.contains("Day 2 announcement")
        })
        .expect("D02 resolution publishes a system announcement row");
    assert!(
        d02_post.body.contains("slot_5 died during night 1")
            && d02_post.body.contains("role: mafia_goon")
            && d02_post
                .body
                .contains("template: mafia_universe_night_death_v1")
            && d02_post.body.contains("audience: public"),
        "thread projection publishes prior-night death announcement"
    );
    assert!(
        d02_post.body.contains("slot_2 died during night 1")
            && d02_post.body.contains("cause: poison")
            && d02_post.body.contains("role: town_vanilla"),
        "thread projection publishes the second prior-night death announcement"
    );
    assert!(
        d02_post
            .body
            .contains("Last words: slot_3 may speak after lynch in D02.")
            && d02_post
                .body
                .contains("template: mafia_universe_last_words_v1")
            && d02_post.body.contains("audience: public")
            && d02_post.body.contains("window: post_lynch"),
        "thread projection publishes lynch last words"
    );
    assert!(
        d02_post
            .body
            .contains("Phase D02 announcement: slot_3 (lynch; template: mafia_universe_lynch_death_v1; audience: public); template: mafia_universe_day_death_v1; audience: public."),
        "thread projection publishes the trailing phase announcement metadata"
    );

    let slots = slot_state(&pool, game).await.unwrap();
    assert!(
        !slots
            .iter()
            .find(|slot| slot.slot_id == "slot_5")
            .unwrap()
            .alive,
        "prior night death folded before day notes"
    );
    assert!(
        !slots
            .iter()
            .find(|slot| slot.slot_id == "slot_2")
            .unwrap()
            .alive,
        "second prior night death folded before day notes"
    );
    assert!(
        !slots
            .iter()
            .find(|slot| slot.slot_id == "slot_3")
            .unwrap()
            .alive,
        "day lynch folded after last words"
    );

    let slots_before = serde_json::to_string(&slots).unwrap();
    let thread_before = serde_json::to_string(&thread).unwrap();
    let phase_before = serde_json::to_string(&phase_state(&pool, game).await.unwrap()).unwrap();
    rebuild(&pool, game).await.expect("projection rebuild");
    assert_eq!(
        slots_before,
        serde_json::to_string(&slot_state(&pool, game).await.unwrap()).unwrap(),
        "slot_state rebuild must preserve day-note-adjacent deaths"
    );
    assert_eq!(
        thread_before,
        serde_json::to_string(
            &projections::thread_view(&pool, game, None, 50)
                .await
                .unwrap()
        )
        .unwrap(),
        "thread_view rebuild must preserve derived public announcement rows"
    );
    assert_eq!(
        phase_before,
        serde_json::to_string(&phase_state(&pool, game).await.unwrap()).unwrap(),
        "derived public announcements must not move the phase cursor"
    );
}

