    assert_eq!(queued[0].queue_id, "poisoned:slot_4:poison_n03");
    assert_eq!(queued[0].target_slot, "slot_4");
    assert_eq!(queued[0].source_action, "poison_n03");
    let queued_before_death = serde_json::to_string(&queued).unwrap();
    rebuild(&pool, game)
        .await
        .expect("projection rebuild before pending poison death");
    assert_eq!(
        queued_before_death,
        serde_json::to_string(&delayed_death_queues(&pool, game).await.unwrap()).unwrap(),
        "delayed_death_queue rebuild must preserve queued poison before death"
    );

    handle(
        &pool,
        &h,
        Command::OpenDayPhase {
            game,
            phase: domain::phase::PhaseId::parse("N04").expect("static test phase id is canonical"),
        },
    )
