// golden: packs/mafiascum/golden/catastrophic_roleblock_suppresses_all_actions.json
async fn host_resolve_phase_self_lynch_win_suppresses_target_lynch_and_faction_wins(pool: PgPool) {
    let host = "host_h";
    let game = Uuid::new_v4();
    let h = user(host);

    handle(
        &pool,
        &h,
        Command::CreateGame {
            game,
            pack: "mafiascum".into(),
            cohost_denied: vec![],
        },
    )
    .await
    .unwrap();
    for (slot, occupant, role) in [
        ("slot_1", "user_1", "jester"),
        ("slot_2", "user_2", "executioner"),
        ("slot_3", "user_3", "vanilla_townie"),
        ("slot_4", "user_4", "mafia_goon"),
        ("slot_5", "user_5", "mafia_goon"),
    ] {
        handle(
            &pool,
            &h,
            Command::AddSlot {
                game,
                slot: slot.into(),
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &h,
            commands::seat_persona! {
                game,
                slot: slot.into(),
                user: occupant,
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &h,
            Command::AssignRole {
                game,
                slot: slot.into(),
                role_key: role.into(),
            },
        )
        .await
        .unwrap();
    }
    handle(
        &pool,
        &h,
        Command::StartGame {
            game,
            phase: domain::phase::PhaseId::parse("N01").expect("static test phase id is canonical"),
        },
    )
    .await
    .unwrap();
    handle(
        &pool,
        &user("user_2"),
        Command::SubmitAction {
            game,
            action_id: "executioner_targets_jester_n01".into(),
            actor_slot: "slot_2".into(),
            template_id: "executioner_target".into(),
            targets: vec!["slot_1".into()],
            grant_id: None,
        },
    )
    .await
    .expect("executioner marks the jester as target");
    handle(&pool, &h, Command::ResolvePhase { game, seed: 7432 })
        .await
        .expect("host resolves executioner target setup");

    let n01_payload =
        stored_payload_where(&pool, game, "ResolutionApplied", &[("phase_id", "N01")]).await;
    let n01 = domain::validate_resolution_json(&n01_payload, domain::RESULT_VERSION).unwrap();
    assert!(n01.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::TargetLynchWinTargeted {
            policy,
            owner,
            target,
            effect,
            source_action,
            ..
        } if policy == "executioner"
            && owner == "slot_2"
            && target == "slot_1"
            && effect == "execution_target"
            && source_action == "executioner_targets_jester_n01"
    )));

    handle(
        &pool,
        &h,
        Command::OpenDayPhase {
            game,
            phase: domain::phase::PhaseId::parse("D01").expect("static test phase id is canonical"),
        },
    )
    .await
    .unwrap();
    for (user_id, actor_slot) in [
        ("user_2", "slot_2"),
        ("user_3", "slot_3"),
        ("user_4", "slot_4"),
    ] {
        handle(
            &pool,
            &user(user_id),
            Command::SubmitVote {
                game,
                actor_slot: actor_slot.into(),
                target: VoteTarget::Slot("slot_1".into()),
            },
        )
        .await
        .unwrap();
    }
    handle(&pool, &h, Command::ResolvePhase { game, seed: 7433 })
        .await
        .expect("host resolves jester self lynch with target/faction collisions");

    let d01_payload =
        stored_payload_where(&pool, game, "ResolutionApplied", &[("phase_id", "D01")]).await;
    let d01 = domain::validate_resolution_json(&d01_payload, domain::RESULT_VERSION).unwrap();
    let wins = d01
        .events
        .iter()
        .filter_map(|indexed| match &indexed.event {
            domain::InnerEvent::WinReached {
                winner, metadata, ..
            } => Some((winner.as_str(), metadata)),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(
        wins.len(),
        1,
        "self-lynch collision should append exactly one terminal WinReached"
    );
    assert!(
        wins.iter().any(|(winner, metadata)| {
            *winner == "jester"
                && metadata.as_ref().is_some_and(|metadata| {
                    metadata.policy.as_deref() == Some("jester")
                        && metadata.target.as_deref() == Some("slot_1")
                        && metadata.role.as_deref() == Some("jester")
                        && metadata.source_event.as_deref() == Some("win.jester")
                })
        }),
        "Jester self-lynch should be the sole terminal win: {wins:?}"
    );
    assert!(
        !wins.iter().any(|(winner, _)| *winner == "executioner"),
        "Jester self-lynch must suppress the pending executioner target-lynch win"
    );
    assert!(
        !wins.iter().any(|(winner, _)| *winner == "mafia"),
        "Jester self-lynch must suppress ordinary post-lynch mafia parity"
    );

    let d01_trace_payload =
        stored_payload_where(&pool, game, "ResolutionTrace", &[("phase_id", "D01")]).await;
    let d01_trace = domain::validate_trace_json(&d01_trace_payload, domain::TRACE_VERSION)
        .expect("valid self-lynch collision trace");
    assert_decision_trace(
        &d01_trace,
        DecisionTraceExpectation {
            stage: "day:lynch_trigger",
            source: "slot:slot_1",
            outcome: "self_lynch_win_reached",
            detail: vec![
                ("policy", serde_json::json!("jester")),
                ("winner", serde_json::json!("jester")),
                ("target", serde_json::json!("slot_1")),
                ("role", serde_json::json!("jester")),
                ("source_event", serde_json::json!("win.jester")),
            ],
        },
    );
    assert_no_decision_trace(
        &d01_trace,
        DecisionTraceExpectation {
            stage: "day:lynch_trigger",
            source: "action:executioner_targets_jester_n01",
            outcome: "target_lynch_win_reached",
            detail: vec![],
        },
    );

    let slots = slot_state(&pool, game).await.unwrap();
    assert!(
        !slots
            .iter()
            .find(|slot| slot.slot_id == "slot_1")
            .unwrap()
            .alive,
        "jester should still be lynched in the collision"
    );
    assert_win_revealed_all_slots(&slots, "jester self-lynch collision win");
    let slots_before = serde_json::to_string(&slots).unwrap();
    rebuild(&pool, game).await.expect("projection rebuild");
    assert_eq!(
        slots_before,
        serde_json::to_string(&slot_state(&pool, game).await.unwrap()).unwrap(),
        "slot_state rebuild must preserve self-lynch collision win"
    );
    let d01_trace_after_rebuild =
        stored_payload_where(&pool, game, "ResolutionTrace", &[("phase_id", "D01")]).await;
    assert_eq!(
        d01_trace_payload, d01_trace_after_rebuild,
        "projection rebuild must not rewrite self-lynch collision trace envelope"
    );
}

