// golden: packs/mafiascum/golden/death_reveal_policy.json
async fn host_resolve_phase_persists_cpr_harm_policy(pool: PgPool) {
    let game = Uuid::new_v4();
    let h = user("host_h");

    handle(
        &pool,
        &h,
        Command::CreateGame {
            game,
            pack: "mafiascum".into(),
            cohost_denied: vec![],
        },
    )
    .await
    .unwrap();
    for (slot, occupant, role) in [
        ("slot_1", "user_1", "mafia_goon"),
        ("slot_2", "user_2", "cpr_doctor"),
        ("slot_3", "user_3", "vanilla_townie"),
        ("slot_4", "user_4", "vanilla_townie"),
    ] {
        handle(
            &pool,
            &h,
            Command::AddSlot {
                game,
                slot: slot.into(),
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &h,
            commands::seat_persona! {
                game,
                slot: slot.into(),
                user: occupant,
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &h,
            Command::AssignRole {
                game,
                slot: slot.into(),
                role_key: role.into(),
            },
        )
        .await
        .unwrap();
    }
    handle(
        &pool,
        &h,
        Command::StartGame {
            game,
            phase: domain::phase::PhaseId::parse("N01").expect("static test phase id is canonical"),
        },
    )
    .await
    .unwrap();

    handle(
        &pool,
        &user("user_2"),
        Command::SubmitAction {
            game,
            action_id: "cpr_unneeded_townie_n01".into(),
            actor_slot: "slot_2".into(),
            template_id: "cpr_protect".into(),
            targets: vec!["slot_3".into()],
            grant_id: None,
        },
    )
    .await
    .expect("CPR Doctor submits protect action");

    handle(&pool, &h, Command::ResolvePhase { game, seed: 7312 })
        .await
        .expect("host resolves CPR harm scenario");

    let applied_payload =
        stored_payload_where(&pool, game, "ResolutionApplied", &[("phase_id", "N01")]).await;
    let applied = domain::validate_resolution_json(&applied_payload, domain::RESULT_VERSION)
        .expect("valid CPR harm resolution");
    assert!(applied.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::PlayerKilled {
            slot_id,
            cause,
            attackers,
            unstoppable,
            ..
        } if slot_id == "slot_3"
            && cause == "cpr_protect"
            && attackers == &vec!["slot_2".to_string()]
            && !*unstoppable
    )));
    assert!(
        !applied.events.iter().any(|indexed| matches!(
            &indexed.event,
            domain::InnerEvent::PlayerSaved { slot_id, .. } if slot_id == "slot_3"
        )),
        "unneeded CPR must not save its target"
    );

    let trace_payload =
        stored_payload_where(&pool, game, "ResolutionTrace", &[("phase_id", "N01")]).await;
    let trace = domain::validate_trace_json(&trace_payload, domain::TRACE_VERSION)
        .expect("valid CPR trace");
    let harm = trace
        .decisions
        .iter()
        .find(|decision| decision.outcome == "cpr_harm_applied")
        .expect("trace should persist CPR harm");
    assert_eq!(harm.stage, "night:cpr");
    assert_eq!(harm.source, "action:cpr_unneeded_townie_n01");
    assert_eq!(harm.detail.at("template_id"), "cpr_protect");
    assert_eq!(harm.detail.at("protector"), "slot_2");
    assert_eq!(harm.detail.at("target"), "slot_3");
    assert_eq!(harm.detail.at("cause"), "cpr_protect");

    let slots = slot_state(&pool, game).await.unwrap();
    assert!(
        slots
            .iter()
            .find(|slot| slot.slot_id == "slot_2")
            .unwrap()
            .alive,
        "CPR Doctor should remain alive after an unneeded CPR harm"
    );
    assert!(
        !slots
            .iter()
            .find(|slot| slot.slot_id == "slot_3")
            .unwrap()
            .alive,
        "unneeded CPR target should die in slot_state"
    );
    let slots_before = serde_json::to_string(&slots).unwrap();
    rebuild(&pool, game).await.expect("projection rebuild");
    assert_eq!(
        slots_before,
        serde_json::to_string(&slot_state(&pool, game).await.unwrap()).unwrap(),
        "slot_state rebuild must preserve CPR harm outcome"
    );
    let trace_after_rebuild =
        stored_payload_where(&pool, game, "ResolutionTrace", &[("phase_id", "N01")]).await;
    assert_eq!(
        trace_payload, trace_after_rebuild,
        "projection rebuild must not rewrite persisted CPR harm trace"
    );
}

