// golden: packs/mafiascum/golden/mass_redirect_rotate.json
async fn host_resolve_phase_persists_mass_redirect_rotate_trace_edges(pool: PgPool) {
    let host = "host_h";
    let game = Uuid::new_v4();
    let h = user(host);

    handle(
        &pool,
        &h,
        Command::CreateGame {
            game,
            pack: "mafiascum".into(),
            cohost_denied: vec![],
        },
    )
    .await
    .unwrap();
    for (slot, role) in [
        ("slot_1", "traffic_controller"),
        ("slot_2", "vanilla_townie"),
        ("slot_3", "vanilla_townie"),
        ("slot_4", "vanilla_townie"),
        ("slot_5", "mafia_goon"),
        ("slot_6", "doctor"),
        ("slot_7", "watcher"),
    ] {
        handle(
            &pool,
            &h,
            Command::AddSlot {
                game,
                slot: slot.into(),
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &h,
            Command::AssignRole {
                game,
                slot: slot.into(),
                role_key: role.into(),
            },
        )
        .await
        .unwrap();
    }
    handle(
        &pool,
        &h,
        Command::StartGame {
            game,
            phase: domain::phase::PhaseId::parse("N01").expect("static test phase id is canonical"),
        },
    )
    .await
    .unwrap();

    append_and_project(
        &pool,
        game,
        &[
            eventstore::EventInput::new(
                "ActionSubmitted",
                1,
                serde_json::json!({
                    "action_id": "rotate_targets_n01",
                    "template_id": "mass_redirect",
                    "actor": "slot_1",
                    "targets": ["slot_2", "slot_3", "slot_4"],
                    "phase_id": "N01"
                }),
                eventstore::ActorId::Slot("slot_1".into()),
                0,
            ),
            eventstore::EventInput::new(
                "ActionSubmitted",
                1,
                serde_json::json!({
                    "action_id": "kill_rotate_n01",
                    "template_id": "factional_kill",
                    "actor": "slot_5",
                    "targets": ["slot_2"],
                    "phase_id": "N01"
                }),
                eventstore::ActorId::Slot("slot_5".into()),
                1,
            ),
            eventstore::EventInput::new(
                "ActionSubmitted",
                1,
                serde_json::json!({
                    "action_id": "protect_rotate_n01",
                    "template_id": "doctor_protect",
                    "actor": "slot_6",
                    "targets": ["slot_3"],
                    "phase_id": "N01"
                }),
                eventstore::ActorId::Slot("slot_6".into()),
                2,
            ),
            eventstore::EventInput::new(
                "ActionSubmitted",
                1,
                serde_json::json!({
                    "action_id": "watch_rotate_n01",
                    "template_id": "watch",
                    "actor": "slot_7",
                    "targets": ["slot_4"],
                    "phase_id": "N01"
                }),
                eventstore::ActorId::Slot("slot_7".into()),
                3,
            ),
        ],
    )
    .await
    .unwrap();
    handle(&pool, &h, Command::ResolvePhase { game, seed: 7319 })
        .await
        .expect("host resolves mass redirect rotate scenario");

    let trace_payload =
        stored_payload_where(&pool, game, "ResolutionTrace", &[("phase_id", "N01")]).await;
    let trace = domain::validate_trace_json(&trace_payload, domain::TRACE_VERSION)
        .expect("valid mass redirect trace");
    let edges = trace
        .edges
        .iter()
        .filter(|edge| edge.kind == "redirect")
        .collect::<Vec<_>>();
    assert_eq!(
        edges.len(),
        3,
        "Rotate should rewrite three target-reading actions"
    );
    assert_eq!(edges[0].from, "kill_rotate_n01:target:0:slot_2");
    assert_eq!(edges[0].to, "kill_rotate_n01:target:0:slot_3");
    assert_eq!(edges[1].from, "protect_rotate_n01:target:0:slot_3");
    assert_eq!(edges[1].to, "protect_rotate_n01:target:0:slot_4");
    assert_eq!(edges[2].from, "watch_rotate_n01:target:0:slot_4");
    assert_eq!(edges[2].to, "watch_rotate_n01:target:0:slot_2");
    for edge in edges {
        assert_eq!(
            edge.detail.at("steps").nth(0).at("redirect_action_id"),
            "rotate_targets_n01"
        );
        assert_eq!(edge.detail.at("steps").nth(0).at("redirect_kind"), "Rotate");
    }

    let applied_payload =
        stored_payload_where(&pool, game, "ResolutionApplied", &[("phase_id", "N01")]).await;
    let applied = domain::validate_resolution_json(&applied_payload, domain::RESULT_VERSION)
        .expect("valid mass redirect resolution");
    assert!(
        applied.events.iter().any(|indexed| matches!(
            &indexed.event,
            domain::InnerEvent::PlayerKilled { slot_id, cause, attackers, .. }
                if slot_id == "slot_3"
                    && cause == "factional_kill"
                    && attackers == &vec!["slot_5".to_string()]
        )),
        "rotated kill should land on slot_3"
    );

    let slots = slot_state(&pool, game).await.unwrap();
    assert!(
        !slots
            .iter()
            .find(|slot| slot.slot_id == "slot_3")
            .unwrap()
            .alive,
        "slot_3 should die after the rotated kill"
    );
    for slot_id in ["slot_2", "slot_4"] {
        assert!(
            slots
                .iter()
                .find(|slot| slot.slot_id == slot_id)
                .unwrap()
                .alive,
            "{slot_id} should remain alive after rotate"
        );
    }

    let slots_before = serde_json::to_string(&slots).unwrap();
    rebuild(&pool, game).await.expect("projection rebuild");
    assert_eq!(
        slots_before,
        serde_json::to_string(&slot_state(&pool, game).await.unwrap()).unwrap(),
        "slot_state rebuild must preserve mass redirect rotate outcome"
    );
    let trace_after_rebuild =
        stored_payload_where(&pool, game, "ResolutionTrace", &[("phase_id", "N01")]).await;
    assert_eq!(
        trace_payload, trace_after_rebuild,
        "projection rebuild must not rewrite persisted mass redirect trace envelope"
    );
}

