    let applied = domain::validate_resolution_json(&applied_payload, domain::RESULT_VERSION)
        .expect("valid non-roleblockable resolution");
    assert!(applied.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::ActionInterfered { actor, reason }
            if actor == "slot_2" && reason == "roleblocked"
    )));
    assert!(
        !applied.events.iter().any(|indexed| matches!(
            &indexed.event,
            domain::InnerEvent::ActionInterfered { actor, reason }
                if actor == "slot_3" && reason == "roleblocked"
        )),
        "non-roleblockable roleblocker action must not be suppressed"
    );
    assert!(
        !applied.events.iter().any(|indexed| matches!(
            &indexed.event,
            domain::InnerEvent::InvestigationResult { investigator, .. }
                if investigator == "slot_2"
        )),
        "roleblocked Cop must not receive an investigation result"
    );

