        stored_payload_where(&pool, game, "ResolutionTrace", &[("phase_id", "N01")]).await;
    let trace = domain::validate_trace_json(&trace_payload, domain::TRACE_VERSION)
        .expect("valid non-roleblockable trace");
    let suppression = trace
        .decisions
        .iter()
        .find(|decision| {
            decision.outcome == "action_suppressed"
                && decision.detail.at("actor") == "slot_2"
                && decision.detail.at("action_id") == "cop_check_n01"
        })
        .expect("trace should persist Cop suppression");
    assert_eq!(
        suppression.detail.at("block_sources").nth(0).at("actor"),
        "slot_3"
    );
    assert_eq!(
        suppression
            .detail
            .at("block_sources")
            .nth(0)
            .at("action_id"),
        "block_cop_n01"
    );
    assert!(
        trace.decisions.iter().all(|decision| {
            decision.outcome != "action_suppressed" || decision.detail.at("actor") != "slot_3"
        }),
        "roleblocker_block must bypass explicit night-resolution suppression"
    );

    let audit = audit_resolution_envelopes(&pool, game)
        .await
        .expect("non-roleblockable resolution audit");
    assert!(
        audit.ok,
        "non-roleblockable resolution audit drifted: {audit:?}"
    );
