// golden: packs/mafiascum/golden/tracker_tracks_visit.json
async fn host_resolve_phase_persists_trigger_loop_cap_trace_note(pool: PgPool) {
    let host = "host_h";
    let game = Uuid::new_v4();
    let h = user(host);

    handle(
        &pool,
        &h,
        Command::CreateGame {
            game,
            pack: "test_trigger_loop_cap".into(),
            cohost_denied: vec![],
        },
    )
    .await
    .unwrap();
    for (slot, role) in [
        ("slot_1", "mafia_goon"),
        ("slot_2", "vengeful_townie"),
        ("slot_3", "vanilla_townie"),
    ] {
        handle(
            &pool,
            &h,
            Command::AddSlot {
                game,
                slot: slot.into(),
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &h,
            Command::AssignRole {
                game,
                slot: slot.into(),
                role_key: role.into(),
            },
        )
        .await
        .unwrap();
    }
    handle(
        &pool,
        &h,
        Command::StartGame {
            game,
            phase: domain::phase::PhaseId::parse("N01").expect("static test phase id is canonical"),
        },
    )
    .await
    .unwrap();

    append_and_project(
        &pool,
        game,
        &[
            EventInput::new(
                "EffectsMarked",
                1,
                serde_json::json!({
                    "effect": "vengeful",
                    "target": "slot_1",
                    "actor": "host_h",
                    "source_action": "fixture:preloaded_vengeful",
                    "phase_id": "N01",
                    "duration": "Persistent",
                    "visibility": "Hidden"
                }),
                ActorId::Host,
                0,
            ),
            EventInput::new(
                "ActionSubmitted",
                1,
                serde_json::json!({
                    "action_id": "kill_vengeful_loop_cap_n01",
                    "template_id": "factional_kill",
                    "actor": "slot_1",
                    "targets": ["slot_2"],
                    "phase_id": "N01"
                }),
                ActorId::Slot("slot_1".into()),
                1,
            ),
        ],
    )
    .await
    .unwrap();

    let snapshot = load_engine_snapshot(&pool, game, &fixture_phase("N01"))
        .await
        .expect("load trigger loop-cap snapshot");
    assert!(
        snapshot
            .slots
            .iter()
            .find(|slot| slot.slot_id == "slot_1")
            .expect("slot_1 snapshot")
            .effects
            .iter()
            .any(|effect| effect == "vengeful"),
        "standalone EffectsMarked must be resolver-visible before resolution"
    );

    handle(&pool, &h, Command::ResolvePhase { game, seed: 7310 })
        .await
        .expect("host resolves trigger loop-cap trace scenario");

    let applied_payload =
        stored_payload_where(&pool, game, "ResolutionApplied", &[("phase_id", "N01")]).await;
    let applied = domain::validate_resolution_json(&applied_payload, domain::RESULT_VERSION)
        .expect("valid trigger loop-cap resolution");
    assert_eq!(applied.counts.kills, 2);
    let vengeful_triggers = applied
        .events
        .iter()
        .filter_map(|indexed| match &indexed.event {
            domain::InnerEvent::Trigger {
                trigger_id,
                payload,
            } if trigger_id == "vengeful_retaliates" => Some((indexed.index, payload)),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(
        vengeful_triggers.len(),
        1,
        "loop-cap should stop before a second retaliatory trigger is emitted"
    );
    let (vengeful_trigger_event_index, vengeful_trigger_payload) = vengeful_triggers[0];
    assert_eq!(vengeful_trigger_payload.on, "Kill");
    assert_eq!(vengeful_trigger_payload.source_target, "slot_2");
    assert_eq!(vengeful_trigger_payload.source_actor, "slot_1");
    assert_eq!(vengeful_trigger_payload.source_cause, "factional_kill");
    assert_eq!(vengeful_trigger_payload.produced_actor, "slot_2");
    assert_eq!(vengeful_trigger_payload.produced_target, "slot_1");
    assert!(vengeful_trigger_payload.actor_filter.is_empty());
    assert!(applied.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::PlayerKilled { slot_id, cause, attackers, .. }
            if slot_id == "slot_2"
                && cause == "factional_kill"
                && attackers == &vec!["slot_1".to_string()]
    )));
    assert!(applied.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::PlayerKilled { slot_id, cause, attackers, .. }
            if slot_id == "slot_1"
                && cause == "vengeful_retaliates"
                && attackers == &vec!["slot_2".to_string()]
    )));

    let trace_payload =
        stored_payload_where(&pool, game, "ResolutionTrace", &[("phase_id", "N01")]).await;
    let trace = domain::validate_trace_json(&trace_payload, domain::TRACE_VERSION)
        .expect("valid trigger loop-cap trace");
    let vengeful_trigger_note = format!(
        "trigger vengeful_retaliates emitted at event_index {vengeful_trigger_event_index}"
    );
    assert!(
        trace
            .notes
            .iter()
            .any(|note| note == &vengeful_trigger_note),
        "ordinary generated-trigger note must survive alongside loop-cap diagnostics"
    );
    assert!(
        trace
            .notes
            .iter()
            .any(|note| note == "trigger loop_cap (1) reached; terminating trigger fixpoint"),
        "trigger truncation must persist in trace notes"
    );
    let vengeful_trigger_decision_source = format!("event_index:{vengeful_trigger_event_index}");
    assert_decision_trace(
        &trace,
        DecisionTraceExpectation {
            stage: "inner_event",
            source: &vengeful_trigger_decision_source,
            outcome: "trigger",
            detail: vec![],
        },
    );
    let vengeful_trigger_decision = trace
        .decisions
        .iter()
        .find(|decision| {
            decision.stage == "inner_event"
                && decision.source == vengeful_trigger_decision_source
                && decision.outcome == "trigger"
        })
        .expect("typed trace decisions should describe the generated trigger event");
    assert_eq!(vengeful_trigger_decision.detail, serde_json::Value::Null);
    assert_trigger_generated_trace(
        &trace,
        TriggerGeneratedTraceExpectation {
            action_id: "vengeful_retaliates",
            on: "Kill",
            source_target: "slot_2",
            source_actor: "slot_1",
            source_cause: "factional_kill",
            produced_actor: "slot_2",
            produced_target: "slot_1",
            actor_filter: None,
            event_index: vengeful_trigger_event_index as i64,
        },
    );

    let slots = slot_state(&pool, game).await.unwrap();
    assert!(
        !slots
            .iter()
            .find(|slot| slot.slot_id == "slot_1")
            .unwrap()
            .alive,
        "generated vengeful kill should kill the original attacker"
    );
    assert!(
        !slots
            .iter()
            .find(|slot| slot.slot_id == "slot_2")
            .unwrap()
            .alive,
        "initial factional kill should kill the vengeful target"
    );
    assert!(
        slots
            .iter()
            .find(|slot| slot.slot_id == "slot_3")
            .unwrap()
            .alive,
        "uninvolved slot should remain alive"
    );
    assert!(
        slot_effects(&pool, game)
            .await
            .unwrap()
            .iter()
            .any(|effect| effect.slot_id == "slot_1" && effect.effect == "vengeful"),
        "standalone effect projection should be rebuildable"
    );

    let slots_before = serde_json::to_string(&slots).unwrap();
    let effects_before = serde_json::to_string(&slot_effects(&pool, game).await.unwrap()).unwrap();
    rebuild(&pool, game).await.expect("projection rebuild");
    assert_eq!(
        slots_before,
        serde_json::to_string(&slot_state(&pool, game).await.unwrap()).unwrap(),
        "slot_state rebuild must preserve trigger loop-cap outcome"
    );
    assert_eq!(
        effects_before,
        serde_json::to_string(&slot_effects(&pool, game).await.unwrap()).unwrap(),
        "slot_effect rebuild must preserve trigger loop-cap fixture effect"
    );
    let trace_after_rebuild =
        stored_payload_where(&pool, game, "ResolutionTrace", &[("phase_id", "N01")]).await;
    assert_eq!(
        trace_payload, trace_after_rebuild,
        "projection rebuild must not rewrite persisted trigger loop-cap trace envelope"
    );
}

