    handle(
        &pool,
        &user("user_2"),
        Command::SubmitAction {
            game,
            action_id: "watcher_watches_target_n01".into(),
            actor_slot: "slot_2".into(),
            template_id: "watch".into(),
            targets: vec!["slot_4".into()],
            grant_id: None,
        },
    )
    .await
    .expect("Watcher submits watch through command validation");
    handle(
        &pool,
        &user("user_3"),
        Command::SubmitAction {
            game,
            action_id: "motion_checks_target_n01".into(),
            actor_slot: "slot_3".into(),
            template_id: "motion_detector".into(),
            targets: vec!["slot_1".into()],
            grant_id: None,
        },
    )
    .await
    .expect("Motion Detector submits motion check through command validation");
