// golden: packs/chinese_structured/golden/idiot_survives_first_lynch.json
async fn host_resolve_phase_carries_chinese_idiot_survival_policy(pool: PgPool) {
    let host = "host_h";
    let h = user(host);
    let game = Uuid::new_v4();

    handle(
        &pool,
        &h,
        Command::CreateGame {
            game,
            pack: "chinese_structured".into(),
            cohost_denied: vec![],
        },
    )
    .await
    .unwrap();
    for (slot, occupant, role) in [
        ("slot_1", "user_1", "idiot"),
        ("slot_2", "user_2", "wolf"),
        ("slot_3", "user_3", "villager"),
        ("slot_4", "user_4", "villager"),
        ("slot_5", "user_5", "villager"),
    ] {
        handle(
            &pool,
            &h,
            Command::AddSlot {
                game,
                slot: slot.into(),
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &h,
            commands::seat_persona! {
                game,
                slot: slot.into(),
                user: occupant,
            },
        )
        .await
        .unwrap();
        handle(
            &pool,
            &h,
            Command::AssignRole {
                game,
                slot: slot.into(),
                role_key: role.into(),
            },
        )
        .await
        .unwrap();
    }

    handle(
        &pool,
        &h,
        Command::StartGame {
            game,
            phase: domain::phase::PhaseId::parse("D01").expect("static test phase id is canonical"),
        },
    )
    .await
    .unwrap();
    for (actor, target) in [
        ("slot_2", "slot_1"),
        ("slot_3", "slot_1"),
        ("slot_4", "slot_1"),
        ("slot_1", "slot_2"),
    ] {
        let user_id = actor.replace("slot", "user");
        handle(
            &pool,
            &user(&user_id),
            Command::SubmitVote {
                game,
                actor_slot: actor.into(),
                target: VoteTarget::Slot(target.into()),
            },
        )
        .await
        .unwrap();
    }
    handle(&pool, &h, Command::ResolvePhase { game, seed: 930301 })
        .await
        .expect("host resolves Chinese Idiot first lynch");

    let day_one_payload =
        stored_payload_where(&pool, game, "ResolutionApplied", &[("phase_id", "D01")]).await;
    let day_one =
        domain::validate_resolution_json(&day_one_payload, domain::RESULT_VERSION).unwrap();
    assert!(day_one.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::PlayerSaved { slot_id, reasons, sources }
            if slot_id == "slot_1"
                && reasons == &vec!["idiot_survival".to_string()]
                && sources == &vec!["slot_1".to_string()]
    )));
    assert!(day_one.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::EffectsMarked {
            effect,
            target,
            actor,
            ..
        }
            if effect == "idiot_vote_loss" && target == "slot_1" && actor == "slot_1"
    )));
    assert!(
        !day_one.events.iter().any(|indexed| matches!(
            &indexed.event,
            domain::InnerEvent::PlayerKilled { slot_id, .. } if slot_id == "slot_1"
        )),
        "first Idiot lynch should save instead of killing"
    );

    let day_one_slots = slot_state(&pool, game).await.unwrap();
    assert!(
        day_one_slots
            .iter()
            .find(|slot| slot.slot_id == "slot_1")
            .unwrap()
            .alive,
        "Idiot should remain alive after first lynch"
    );
    assert!(
        slot_effects(&pool, game)
            .await
            .unwrap()
            .iter()
            .any(|effect| effect.slot_id == "slot_1" && effect.effect == "idiot_vote_loss"),
        "Idiot survival should project the vote-loss effect"
    );

    handle(
        &pool,
        &h,
        Command::StartGame {
            game,
            phase: domain::phase::PhaseId::parse("D02").expect("static test phase id is canonical"),
        },
    )
    .await
    .unwrap();
    let vote_lost_err = handle(
        &pool,
        &user("user_1"),
        Command::SubmitVote {
            game,
            actor_slot: "slot_1".into(),
            target: VoteTarget::Slot("slot_2".into()),
        },
    )
    .await
    .expect_err("vote-lost Chinese Idiot cannot submit later ballots");
    assert_eq!(vote_lost_err, Reject::VoteNotAllowed);
    let rejected_vote_count: i64 = stored_event_count_where(
        &pool,
        game,
        "VoteSubmitted",
        &[("phase_id", "D02"), ("actor", "slot_1")],
    )
    .await as i64;
    assert_eq!(
        rejected_vote_count, 0,
        "vote-lost Idiot rejection must append no VoteSubmitted"
    );
    for (actor, target) in [
        ("slot_2", "slot_1"),
        ("slot_3", "slot_1"),
        ("slot_4", "slot_1"),
    ] {
        let user_id = actor.replace("slot", "user");
        handle(
            &pool,
            &user(&user_id),
            Command::SubmitVote {
                game,
                actor_slot: actor.into(),
                target: VoteTarget::Slot(target.into()),
            },
        )
        .await
        .unwrap();
    }
    handle(&pool, &h, Command::ResolvePhase { game, seed: 930302 })
        .await
        .expect("host resolves Chinese Idiot later lynch");

    let day_two_payload =
        stored_payload_where(&pool, game, "ResolutionApplied", &[("phase_id", "D02")]).await;
    let day_two =
        domain::validate_resolution_json(&day_two_payload, domain::RESULT_VERSION).unwrap();
    let outcome = day_two
        .events
        .iter()
        .find_map(|indexed| match &indexed.event {
            domain::InnerEvent::DayVoteOutcome(outcome) => Some(outcome),
            _ => None,
        })
        .expect("D02 should emit a day vote outcome");
    assert_eq!(outcome.winner.as_deref(), Some("slot_1"));
    assert_eq!(outcome.weights.get("slot_1").copied(), Some(0.0));
    assert_eq!(
        outcome.votes.get("slot_1"),
        None,
        "vote-lost Idiot should not have a recorded D02 ballot"
    );
    assert_eq!(
        outcome.tallies.get("slot_2"),
        None,
        "rejected vote-lost ballot should not create a zero-tally candidate row"
    );
    assert!(
        (outcome.total_weight - 4.0).abs() < f64::EPSILON,
        "Idiot vote-loss effect should remove exactly one vote weight"
    );
    assert!(day_two.events.iter().any(|indexed| matches!(
        &indexed.event,
        domain::InnerEvent::PlayerKilled { slot_id, cause, .. }
            if slot_id == "slot_1" && cause == "day_vote"
    )));

    let slots = slot_state(&pool, game).await.unwrap();
    assert!(
        !slots
            .iter()
            .find(|slot| slot.slot_id == "slot_1")
            .unwrap()
            .alive,
        "Idiot should die to a later lynch after vote loss is present"
    );
    let effects = slot_effects(&pool, game).await.unwrap();
    let slots_before = serde_json::to_string(&slots).unwrap();
    let effects_before = serde_json::to_string(&effects).unwrap();
    rebuild(&pool, game).await.expect("projection rebuild");
    assert_eq!(
        slots_before,
        serde_json::to_string(&slot_state(&pool, game).await.unwrap()).unwrap(),
        "slot_state rebuild must preserve Chinese Idiot lynch state"
    );
    assert_eq!(
        effects_before,
        serde_json::to_string(&slot_effects(&pool, game).await.unwrap()).unwrap(),
        "slot_effect rebuild must preserve Chinese Idiot vote-loss state"
    );
}

